#include <Aevrynd/Camera.h>
#include <Aevrynd/Mesh3D.h>
#include <Aevrynd/Renderer.h>
#include <Windows.h>
#include <algorithm>
#include <chrono>
#include <iostream>
#include <vector>
using namespace Aevrynd;
struct Samples{std::vector<uint64_t> wall,submission,prep,present,gpu;};
static uint64_t P(std::vector<uint64_t> v,size_t p){std::ranges::sort(v);return v[(v.size()-1)*p/100];}
static void Sample(D3D12Renderer& r,const DrawList& d,GpuInstanceSubmissionMode3D mode,Samples& s){r.SetGpuInstanceCullingSettings({true,500.f,mode});const auto b=std::chrono::steady_clock::now();r.Render(d,{0,0,0,1});const auto e=std::chrono::steady_clock::now();r.WaitIdle();const auto x=r.GetStats();s.wall.push_back(uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(e-b).count()));s.submission.push_back(x.lastGpuInstanceSubmissionCpuNanoseconds);s.prep.push_back(x.lastRenderPreparationCpuNanoseconds+x.lastRenderCommandRecordingCpuNanoseconds);s.present.push_back(x.lastRenderPresentCpuNanoseconds);s.gpu.push_back(x.lastGpuFrameNanoseconds);}
int main(){constexpr size_t Groups=1024;HINSTANCE h=GetModuleHandleW(nullptr);WNDCLASSW wc{};wc.lpfnWndProc=DefWindowProcW;wc.hInstance=h;wc.lpszClassName=L"AevryndGpuMultiGroupBenchmark";RegisterClassW(&wc);HWND w=CreateWindowW(wc.lpszClassName,L"GPU multi-group benchmark",WS_OVERLAPPED,0,0,1920,1080,nullptr,nullptr,h,nullptr);if(!w)return 1;D3D12Renderer r;r.Initialize(w,1920,1080,1920,1080,false);r.SetQualitySettings({false,false,false,false});DrawList d;Camera3D camera{{0,0,-12},{0,0,0},{0,1,0},{}};d.SetViewProjection(CreateViewProjectionMatrix(camera,1920.f/1080.f));const Mesh3D source=Mesh3D::CreateUnitSphere(12,8);std::vector<MeshHandle3D> meshes;for(size_t g=0;g<Groups;++g){Mesh3D unique=source;unique.vertices[0].x+=float(g+1)*.00001f;const auto mesh=r.CreateMesh(unique.vertices,unique.indices);if(!mesh)return 2;meshes.push_back(mesh);for(size_t i=0;i<8;++i)if(!d.MeshInstance(mesh,CreateTranslationMatrix({float(int(g%32)-16)*.15f,float(int(g/32)-16)*.12f,float(i)*.03f}),{1,1,1,1},{},MeshRenderLayer3D::Opaque,{},.25f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false,1,0,false,DirectionalShadowAllCascades3D,ShadowCascadeSelection3D::Automatic,Matrix4::Identity(),false,1.f,MaterialAlphaMode3D::Opaque,.5f,g>=Groups/2))return 3;}Samples a,m;for(size_t i=0;i<16;++i){Sample(r,d,GpuInstanceSubmissionMode3D::Aggregate,a);Sample(r,d,GpuInstanceSubmissionMode3D::MultiGroup,m);}a={};m={};size_t wallWins{},submissionWins{},prepWins{};for(size_t i=0;i<101;++i){const size_t ai=a.wall.size(),mi=m.wall.size();if(i&1){Sample(r,d,GpuInstanceSubmissionMode3D::MultiGroup,m);Sample(r,d,GpuInstanceSubmissionMode3D::Aggregate,a);}else{Sample(r,d,GpuInstanceSubmissionMode3D::Aggregate,a);Sample(r,d,GpuInstanceSubmissionMode3D::MultiGroup,m);}wallWins+=m.wall[mi]<a.wall[ai];submissionWins+=m.submission[mi]<a.submission[ai];prepWins+=m.prep[mi]<a.prep[ai];}r.SetGpuInstanceCullingSettings({true,500.f,GpuInstanceSubmissionMode3D::MultiGroup});r.Render(d,{0,0,0,1});r.WaitIdle();const auto stats=r.GetStats();for(auto mesh:meshes)r.DestroyMesh(mesh);r.WaitIdle();DestroyWindow(w);const auto sa=P(a.submission,50),sm=P(m.submission,50),sa95=P(a.submission,95),sm95=P(m.submission,95),pa=P(a.prep,50),pm=P(m.prep,50),pa95=P(a.prep,95),pm95=P(m.prep,95),ga=P(a.gpu,50),gm=P(m.gpu,50);const double sg=1.-double(sm)/sa,sg95=1.-double(sm95)/sa95,pg=1.-double(pm)/pa,pg95=1.-double(pm95)/pa95,gpuRegression=double(gm)/ga-1.;std::cout<<"groups="<<Groups<<" instances="<<Groups*8<<" wall_median="<<P(a.wall,50)<<"->"<<P(m.wall,50)<<" wall_p95="<<P(a.wall,95)<<"->"<<P(m.wall,95)<<" wall_win_rate="<<double(wallWins)/101.<<" present_median="<<P(a.present,50)<<"->"<<P(m.present,50)<<" submission_gain="<<sg<<" submission_p95_gain="<<sg95<<" submission_win_rate="<<double(submissionWins)/101.<<" prep_record_gain="<<pg<<" prep_record_p95_gain="<<pg95<<" prep_record_win_rate="<<double(prepWins)/101.<<" gpu_regression="<<gpuRegression<<" buckets="<<stats.lastGpuInstanceSubmissionBuckets<<" commands="<<stats.lastGpuInstanceSubmissionCommands<<" calls="<<stats.lastGpuInstanceSubmissionCalls<<'\n';const bool gate=(sg>=.25&&sg95>=.25&&double(submissionWins)/101.>=.70)||(pg>=.25&&pg95>=.25&&double(prepWins)/101.>=.70);return gate&&gpuRegression<=.05&&stats.lastGpuInstanceSubmissionBuckets==2&&stats.lastGpuInstanceSubmissionCommands==Groups&&stats.lastGpuInstanceSubmissionCalls==2?0:4;}
